import{_ as c,C as n,o as d,c as p,E as t,w as a,j as e,a as r}from"./chunks/framework.CWBU7zwD.js";const b=JSON.parse(`{"title":"","description":"","frontmatter":{"pageClass":"st-page-large","parcours":"PO","id":"QZ","titre":"Quiz « rôle inversé » : auditer un dossier produit par l'IA","duree":20,"quiz":{"doc":[{"t":"title","x":"DOSSIER DE FONCTIONNALITÉ — LAN-111 Départ express"},{"t":"sub","x":"(rédigé par l'assistant IA pour l'équipe Lanterne — chiffres fictifs)"},{"t":"h","x":"1. Synthèse de l'atelier du sprint 14"},{"t":"p","x":"Besoin : régler sa note dans l'application et partir sans passer au comptoir ; la réception garde la main sur les contestations."},{"t":"p","x":"Réserve : NTE-02 accueille beaucoup de familles qui veulent vérifier la note avec quelqu'un."},{"t":"p","x":"Décision de l'atelier : le départ express ouvrira à LYS-03 au sprint 16.","d":"D1"},{"t":"p","x":"Actions : Yann envoie la documentation ; Josiane confirme le temps de contrôle du minibar ; Céline confirmera si un pilote est possible, sans date à ce stade."},{"t":"h","x":"2. Fiche fonctionnalité"},{"t":"p","x":"Statut : prête (DoR vérifiée).","d":"D2"},{"t":"p","x":"Critère de succès : à définir plus tard.","d":"D2"},{"t":"p","x":"Règle rappelée : le client voit chaque ligne de sa note et le montant total avant de confirmer (DE-2)."},{"t":"h","x":"3. Journal des échanges avec les experts"},{"t":"p","x":"Minibar : Josiane (étages) demande 30 minutes pour contrôler ; la règle du parcours revient à Céline."},{"t":"p","x":"Décision d'Armelle : le minibar n'est plus contrôlé par les étages.","d":"D3"},{"t":"h","x":"4. Maquette retenue"},{"t":"p","x":"Écran 1 « Départ express — votre note » : la liste des consommations du séjour.","d":"D4"},{"t":"p","x":"Écran 2 « Départ express — règlement » : bouton « Confirmer et partir ».","d":"D4"},{"t":"p","x":"Écran 3 « Départ express — confirmation » : récapitulatif du montant total réglé.","d":"D4"},{"t":"h","x":"5. User stories"},{"t":"p","x":"LAN-112 — CA1 : étant donné un séjour dont le départ est aujourd'hui, quand le client ouvre le départ express, alors il voit chaque ligne de sa note et le total."},{"t":"p","x":"LAN-113 — CA2 : étant donné une pré-autorisation qui couvre le montant, quand le client confirme, alors le paiement est rapide et sans friction.","d":"D5"},{"t":"h","x":"6. Priorités du sprint 16"},{"t":"p","x":"Ordre : LAN-112, LAN-113, LAN-115, LAN-116, puis LAN-118 en dernier : il n'apporte pas de valeur visible au client.","d":"D6"},{"t":"p","x":"Constat LAN-118 : sévérité haute, correction exigée sous 30 jours."},{"t":"h","x":"7. Plan du sprint 16"},{"t":"p","x":"Vélocité moyenne des six derniers sprints : 21 points. Malo et Leïla sont absents 5 jours au total."},{"t":"p","x":"Capacité retenue : 21 points. Engagement : 23 points.","d":"D7"},{"t":"h","x":"8. Note de version"},{"t":"p","x":"Les clients des trois hôtels pilotes peuvent désormais régler leur note et contester une ligne depuis l'application.","d":"D8"},{"t":"p","x":"Activation : LYS-03 seulement. LAN-116 (contester une ligne) : non livré."}],"defauts":[{"n":"D1","loc":"Section 1 : « Décision de l'atelier : le départ express ouvrira à LYS-03 au sprint 16 »","def":"Une proposition est devenue une décision, avec une date, alors que la section Actions dit que Céline confirmera si un pilote est possible, sans date.","crit":"La trouvaille désigne cette « décision », ET dit que personne ne l'a prise (c'était une proposition), ou qu'elle contredit l'action de Céline « sans date ».","mod":"M1","h1":"Relis la section 1 : qui décide de quoi, et quand ?","h2":"La section Actions confirme-t-elle la « décision » qui la précède ?","exp":"Une synthèse ne retient une décision que si quelqu'un l'a prise. Ici, Céline n'a fait que proposer une piste : la date du sprint 16 n'existe nulle part."},{"n":"D2","loc":"Section 2 : « Statut : prête (DoR vérifiée) » avec « Critère de succès : à définir plus tard »","def":"La fiche est déclarée prête alors qu'un critère de la DoR, le critère de succès mesurable rattaché à un objectif, n'est pas rempli.","crit":"La trouvaille désigne le statut « prête » ou la DoR « vérifiée », ET dit qu'un critère manque (le critère de succès), ou que la DoR ne peut pas être remplie.","mod":"M2","h1":"Que contient la section 2, ligne par ligne ?","h2":"Une fiche sans critère de succès remplit-elle la DoR de l'équipe ?","exp":"« Prêt » se coche critère par critère. Une fiche bien rédigée sans critère de succès n'est pas prête : il faut le demander à Céline, ou qu'elle assume « aucun »."},{"n":"D3","loc":"Section 3 : « Décision d'Armelle : le minibar n'est plus contrôlé par les étages »","def":"Un avis est devenu une décision, attribuée à la mauvaise personne : la ligne précédente dit que la règle revient à Céline, et Josiane demande à contrôler.","crit":"La trouvaille désigne cette décision, ET dit qu'Armelle n'a pas tranché (un avis), que la décision revient à Céline, ou qu'elle contredit la demande de Josiane.","mod":"M3","h1":"Relis la section 3 : à qui revient la règle du minibar ?","h2":"La « décision » attribuée à Armelle est-elle cohérente avec la ligne qui la précède ?","exp":"Un journal de décisions attribue chaque décision à la personne qui l'a prise. Ici, le sujet est ouvert : deux avis divergents, et une décision qui revient à Céline."},{"n":"D4","loc":"Section 4 : écran 1 « la liste des consommations du séjour », sans total ; écran 2 « Confirmer et partir », puis écran 3 « récapitulatif du montant total réglé »","def":"Le montant total n'apparaît qu'après la confirmation, alors que la règle DE-2, rappelée en section 2, exige de le montrer avant.","crit":"La trouvaille désigne la maquette (écran 1, 2 ou 3), ET dit que le total n'apparaît pas avant la confirmation, ou que la règle DE-2 n'est pas respectée.","mod":"M4","h1":"Relis la section 4 : à quel moment le client voit-il le montant total ?","h2":"Que dit la règle rappelée à la fin de la section 2 ?","exp":"Un écran se vérifie contre les règles. Ici, le client confirme avant de connaître le total : c'est exactement ce que DE-2 interdit."},{"n":"D5","loc":"Section 5 : critère de LAN-113 « … alors le paiement est rapide et sans friction »","def":"Un critère d'acceptation à adjectifs : aucun test ne peut dire s'il est réussi ou raté.","crit":"La trouvaille désigne ce critère, ET dit qu'il n'est pas vérifiable, qu'il contient des adjectifs, ou qu'il lui manque une valeur ou un résultat observable.","mod":"M5","h1":"Que vérifie chacun des critères de la section 5 ?","h2":"Comment écrirais-tu le test qui prouve « rapide et sans friction » ?","exp":"Un critère se vérifie par un test : un résultat observable (« le montant est encaissé et le client voit la confirmation »), ou une valeur écrite dans la fiche. Sinon, une question."},{"n":"D6","loc":"Section 6 : « LAN-118 en dernier : il n'apporte pas de valeur visible au client »","def":"Une contrainte de sécurité datée est reléguée, alors que la ligne suivante dit « sévérité haute, correction exigée sous 30 jours ».","crit":"La trouvaille désigne la place de LAN-118, ET dit que sa sévérité ou son échéance de 30 jours impose de le planifier, ou que l'absence de valeur visible n'est pas un critère pour une faille.","mod":"M6","h1":"Relis la section 6 : qu'est-ce qui fixe l'urgence de LAN-118 ?","h2":"L'échéance de correction tombe-t-elle avant ou après le sprint suivant ?","exp":"Une faille de sévérité haute, avec une échéance, n'est pas une question de valeur visible : elle entre dans le sprint, avant ce qui peut attendre."},{"n":"D7","loc":"Section 7 : « Capacité retenue : 21 points. Engagement : 23 points »","def":"Les absences (5 jours) ne sont pas déduites de la capacité, et l'engagement dépasse même cette capacité.","crit":"La trouvaille désigne la capacité ou l'engagement, ET dit que les absences ne sont pas déduites, ou que l'engagement dépasse la capacité.","mod":"M7","h1":"Relis la section 7 : que deviennent les jours d'absence dans le calcul ?","h2":"L'engagement tient-il dans la capacité retenue ?","exp":"La capacité se calcule avec les disponibilités réelles. Ici, 5 jours d'absence disparaissent du calcul, et l'équipe s'engage au-delà du chiffre retenu."},{"n":"D8","loc":"Section 8 : « Les clients des trois hôtels pilotes peuvent désormais régler leur note et contester une ligne »","def":"La note de version annonce ce qui n'est ni activé (trois hôtels au lieu de LYS-03) ni livré (contester une ligne), comme le dit la ligne suivante.","crit":"La trouvaille désigne la note de version, ET dit que l'activation est limitée à LYS-03, ou que la contestation (LAN-116) n'est pas livrée.","mod":"M8","h1":"Relis la section 8 : la note de version et la ligne qui la suit disent-elles la même chose ?","h2":"Dans combien d'hôtels le départ express est-il activé ?","exp":"La documentation dit ce que le produit fait vraiment, là où il le fait. Prévu n'est pas livré, et activé ici n'est pas activé partout."}]}},"headers":[],"relativePath":"po/quiz.md","filePath":"po/quiz.md"}`),m={name:"po/quiz.md"};function v(f,i,q,g,x,h){const s=n("Etape"),l=n("Livrable"),o=n("Quiz",!0),u=n("Module");return d(),p("div",null,[t(u,null,{default:a(()=>[t(s,{cle:"qz-situation",titre:"La situation"},{default:a(()=>[...i[0]||(i[0]=[e("div",{class:"st-box st-situation"},[e("p",{class:"st-lbl"},"Situation"),e("p",null,[r("Yann a demandé à son assistant IA un "),e("strong",null,"dossier de fonctionnalité"),r(" du départ express, à présenter en revue de sprint : synthèse de l'atelier, fiche, journal des experts, maquette, user stories, priorités, plan de sprint et note de version.")]),e("p",null,"Avant de le diffuser, il te demande de le relire, comme si c'était à toi de le valider."),e("p",null,"Tout ce dont tu as besoin est dans le dossier affiché à l'étape suivante. Les chiffres qu'il contient sont fictifs.")],-1)])]),_:1}),t(s,{cle:"qz-livrable",titre:"Le livrable à auditer"},{default:a(()=>[i[1]||(i[1]=e("p",null,"Lis le livrable en entier. Tu le retrouveras à côté de ta liste de trouvailles à l'étape suivante.",-1)),t(l)]),_:1}),t(s,{cle:"qz-mission",titre:"La mission"},{default:a(()=>[t(o)]),_:1})]),_:1})])}const D=c(m,[["render",v]]);export{b as __pageData,D as default};
